8	export class ResizeSetup
9	  implements ISetup<[Engine, ResizeSetupOptions | number | undefined], void>
10	{
11	  private _engine: Engine | null = null;
12	  private _scrollDriver: { refresh?: () => void } | null = null;
13	  private _debounce: Debounce | null = null;
14	  private _boundHandler: (() => void) | null = null;
15	  private _visualViewportHandler: (() => void) | null = null;
16	  private _disposed = false;
17	
18	  init(
19	    engine: Engine,
20	    options: ResizeSetupOptions | number | undefined = 250,
21	  ): void {
22	    this.startListening(engine, options);
23	  }
24	
25	  startListening(
26	    engine: Engine,
27	    options: ResizeSetupOptions | number = 250,
28	  ): void {
29	    if (this._disposed || this._boundHandler) return;
30	    const opts: ResizeSetupOptions =
31	      typeof options === "number" ? { debounceMs: options } : options;
32	    const delayMs = opts.debounceMs ?? 250;
33	    this._engine = engine;
34	    this._scrollDriver = opts.scrollDriver ?? null;
35	    this._debounce = new Debounce(delayMs);
36	    this._boundHandler = (): void => {
37	      this._debounce?.runDebounce(() => {
38	        const runtime = ResponsiveRuntime.getDefault();
39	        runtime.init();
40	        const snapshot = runtime.updateFromWindow();
41	        this._engine?.applyResponsiveSnapshot(snapshot);
42	        this._scrollDriver?.refresh?.();
43	      });
44	    };
45	    const runtime = ResponsiveRuntime.getDefault();
46	    runtime.init();
47	    this._engine.applyResponsiveSnapshot(runtime.getSnapshot());
48	    window.addEventListener("resize", this._boundHandler);
49	    if (typeof window !== "undefined" && window.visualViewport != null) {
50	      this._visualViewportHandler = this._boundHandler;
51	      window.visualViewport.addEventListener("resize", this._visualViewportHandler);
52	    }
53	  }
54	
55	  register(engine: Engine, options: ResizeSetupOptions | number = 250): void {
56	    this.startListening(engine, options);
57	  }
58	
59	  dispose(): void {
60	    this.stopListening();
61	  }
62	
63	  stopListening(): void {
64	    if (this._disposed) return;
65	    this._disposed = true;
66	    if (this._boundHandler) {
67	      window.removeEventListener("resize", this._boundHandler);
68	      this._boundHandler = null;
69	    }
70	    if (this._visualViewportHandler && typeof window !== "undefined" && window.visualViewport != null) {
71	      window.visualViewport.removeEventListener("resize", this._visualViewportHandler);
72	      this._visualViewportHandler = null;
73	    }
74	    this._debounce?.dispose();
75	    this._debounce = null;
76	    this._engine = null;
77	    this._scrollDriver = null;
78	  }
79	}
